(() => {
  const segs = [...document.querySelectorAll('[data-settings-body] [role="radiogroup"]')];
  if (segs.length === 0) throw new Error('没有找到分段控件');
  const heights = []; const per = []; const unfilled = [];
  for (const g of segs) {
    const btns = [...g.querySelectorAll('button')];
    const hs = btns.map((b) => Math.round(b.getBoundingClientRect().height));
    heights.push(...hs);
    per.push({ label: (g.getAttribute('aria-label') || '').slice(0, 10), hs: [...new Set(hs)] });
    const gr = g.getBoundingClientRect();
    const rows = [...g.children];
    const last = rows[rows.length - 1];
    if (last) {
      const lr = last.getBoundingClientRect();
      if (gr.right - lr.right > 2) unfilled.push({ label: (g.getAttribute('aria-label') || '').slice(0, 10), gap: Math.round(gr.right - lr.right) });
    }
  }
  const min = Math.min(...heights); const max = Math.max(...heights);
  const multi = per.filter((p) => p.hs.length > 1);
  if (multi.length > 0) throw new Error('同一分组内分段高度不一致: ' + JSON.stringify(multi));
  if (unfilled.length > 0) throw new Error('分段控件末行没有铺满整行: ' + JSON.stringify(unfilled));
  if (min < 30) throw new Error('分段选项过矮（<30px）: ' + JSON.stringify(per.filter((p) => Math.min(...p.hs) < 30).slice(0, 4)));
  if (max > 90) throw new Error('分段选项过高（>90px，说明被挤成窄条）: ' + JSON.stringify(per.filter((p) => Math.max(...p.hs) > 90).slice(0, 4)));
  return { segmentedGroups: segs.length, buttons: heights.length, minH: min, maxH: max };
})()

(() => {
  const measure = (sel) => [...document.querySelectorAll(sel)].map((el) => {
    const r = el.getBoundingClientRect()
    const range = document.createRange()
    range.selectNodeContents(el)
    const tops = new Set([...range.getClientRects()].map((x) => Math.round(x.top)))
    return { w: Math.round(r.width), lines: tops.size, text: (el.textContent || '').trim().slice(0, 24) }
  })
  const labels = measure('[data-setting-label]')
  const hints = measure('[data-setting-hint]')
  // 标签有 9em 下限（≈6 个中文字）：3 行以上才说明被压成了竖排
  const badLabels = labels.filter((x) => x.w > 0 && x.lines >= 3)
  const badHints = hints.filter((x) => x.w > 0 && x.w < 240 && x.lines >= 4)
  if (badLabels.length) throw new Error('设置标签被挤成竖排: ' + JSON.stringify(badLabels.slice(0, 4)))
  if (badHints.length) throw new Error('设置说明变成窄长段落: ' + JSON.stringify(badHints.slice(0, 4)))
  return { labels: labels.length, hints: hints.length, minLabelW: Math.min(...labels.map((x) => x.w)), minHintW: Math.min(...hints.map((x) => x.w)), badLabels: 0, badHints: 0 }
})()
